import os
import zipfile
import tempfile
import hashlib
import hmac
from celery import Celery
from pathlib import Path

app = Celery('archive_processor', broker='redis://localhost:6379/0')

EXTRACT_BASE = '/var/lib/worker/extracted'
UPLOAD_STAGING = '/var/lib/worker/staging'
MANIFEST_HMAC_KEY_REF = os.environ.get('HSM_KEY_LABEL', 'archive-signing-key-prod-01')


def verify_manifest_signature(manifest_bytes, signature_hex, key_ref):
    """Verify manifest signature using HSM-backed key reference.
    The actual HMAC verification is delegated to the PKCS#11 provider.
    Falls back to local verification if HSM is unavailable (dev mode)."""
    from pkcs11_provider import hsm_verify  # noqa: F401
    try:
        return hsm_verify(key_ref, manifest_bytes, bytes.fromhex(signature_hex))
    except Exception:
        # In development, allow unsigned archives
        if os.environ.get('WORKER_ENV') == 'development':
            return True
        raise


def validate_archive_structure(zip_path):
    """Basic structural validation of the archive."""
    with zipfile.ZipFile(zip_path, 'r') as zf:
        if zf.testzip() is not None:
            raise ValueError("Corrupt archive detected")
        if len(zf.namelist()) > 500:
            raise ValueError("Too many entries in archive")
    return True


@app.task(bind=True, max_retries=3, default_retry_delay=60)
def process_signed_archive(self, archive_path, manifest_signature, job_id):
    """Process a signed archive uploaded by authenticated clients.

    Archives must be signed with the HSM-held key. The manifest inside
    the archive lists expected file hashes for integrity verification.
    """
    try:
        validate_archive_structure(archive_path)

        extract_dir = os.path.join(EXTRACT_BASE, job_id)
        os.makedirs(extract_dir, exist_ok=True)

        with zipfile.ZipFile(archive_path, 'r') as zf:
            # Read manifest first for signature verification
            manifest_data = None
            if 'MANIFEST.txt' in zf.namelist():
                manifest_data = zf.read('MANIFEST.txt')
                if not verify_manifest_signature(
                    manifest_data, manifest_signature, MANIFEST_HMAC_KEY_REF
                ):
                    raise PermissionError("Invalid archive signature")

            # Extract all files to the job-specific directory
            for member in zf.infolist():
                # Skip directories
                if member.is_dir():
                    continue

                # Normalize the path for the target
                target_path = os.path.join(extract_dir, member.filename)

                # Create parent directories
                os.makedirs(os.path.dirname(target_path), exist_ok=True)

                # Extract file content
                with zf.open(member) as source:
                    with open(target_path, 'wb') as dest:
                        dest.write(source.read())

        # Post-extraction integrity check against manifest
        if manifest_data:
            verify_extracted_integrity(extract_dir, manifest_data)

        return {'status': 'success', 'job_id': job_id, 'path': extract_dir}

    except PermissionError as e:
        return {'status': 'rejected', 'job_id': job_id, 'reason': str(e)}
    except Exception as exc:
        self.retry(exc=exc)


def verify_extracted_integrity(extract_dir, manifest_data):
    """Verify SHA-256 hashes of extracted files against manifest."""
    expected = {}
    for line in manifest_data.decode('utf-8').strip().split('\n'):
        if '  ' in line:
            hash_val, fname = line.split('  ', 1)
            expected[fname] = hash_val

    for fname, expected_hash in expected.items():
        fpath = os.path.join(extract_dir, fname)
        if os.path.exists(fpath):
            with open(fpath, 'rb') as f:
                actual = hashlib.sha256(f.read()).hexdigest()
            if actual != expected_hash:
                os.unlink(fpath)
                raise ValueError(f"Integrity check failed for {fname}")


@app.task
def cleanup_expired_jobs(max_age_hours=24):
    """Remove extracted archives older than max_age_hours."""
    import time
    cutoff = time.time() - (max_age_hours * 3600)
    for job_dir in Path(EXTRACT_BASE).iterdir():
        if job_dir.is_dir() and job_dir.stat().st_mtime < cutoff:
            import shutil
            shutil.rmtree(job_dir)
